CREATE TABLE IF NOT EXISTS projects(id uuid PRIMARY KEY,owner_id varchar(64) NOT NULL,name varchar(100) NOT NULL,crop varchar(80) NOT NULL DEFAULT '',created timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS memberships(project_id uuid REFERENCES projects(id) ON DELETE CASCADE,user_id varchar(64) NOT NULL,role varchar(20) NOT NULL CHECK(role IN ('ADMIN','COLLECTOR','REVIEWER')),PRIMARY KEY(project_id,user_id));
CREATE TABLE IF NOT EXISTS devices(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id),owner_id varchar(64) NOT NULL,name varchar(100) NOT NULL,kind varchar(40) NOT NULL,status varchar(20) NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','paused','rejected')),last_seen timestamptz,created timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS platform_samples(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id),owner_id varchar(64) NOT NULL,source_id varchar(64),object_key varchar(300) NOT NULL,sha256 char(64) NOT NULL,quality jsonb NOT NULL DEFAULT '{}',model_answer text NOT NULL DEFAULT '',label varchar(100) NOT NULL DEFAULT '',review_status varchar(20) NOT NULL DEFAULT 'pending' CHECK(review_status IN ('pending','confirmed','uncertain','rephoto')),notes text NOT NULL DEFAULT '',reviewer varchar(64),created timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,source_id));
CREATE TABLE IF NOT EXISTS tasks(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id),owner_id varchar(64) NOT NULL,kind varchar(40) NOT NULL,args jsonb NOT NULL,status varchar(20) NOT NULL DEFAULT 'queued',progress integer NOT NULL DEFAULT 0 CHECK(progress BETWEEN 0 AND 100),result jsonb,error text,attempts integer NOT NULL DEFAULT 0,created timestamptz NOT NULL DEFAULT now(),started timestamptz,finished timestamptz);
CREATE TABLE IF NOT EXISTS reviews(id uuid PRIMARY KEY,sample_id uuid NOT NULL REFERENCES platform_samples(id),actor_id varchar(64) NOT NULL,status varchar(20) NOT NULL,label varchar(100) NOT NULL,notes text NOT NULL,created timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_log(id bigserial PRIMARY KEY,project_id uuid,actor_id varchar(64) NOT NULL,action varchar(80) NOT NULL,target_id varchar(64),detail jsonb NOT NULL DEFAULT '{}',created timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outbox(id uuid PRIMARY KEY,event_type varchar(80) NOT NULL,owner_id varchar(64) NOT NULL,project_id uuid NOT NULL,payload jsonb NOT NULL,created timestamptz NOT NULL DEFAULT now(),kafka_sent boolean NOT NULL DEFAULT false,dispatched boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS model_experiments(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id),owner_id varchar(64) NOT NULL,model varchar(100) NOT NULL,dataset_version varchar(100) NOT NULL,metrics jsonb NOT NULL,artifact_key varchar(300),mlflow_run varchar(100),created timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS dataset_versions(id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES projects(id),owner_id varchar(64) NOT NULL,manifest_sha char(64) NOT NULL,object_key varchar(300) NOT NULL,rows integer NOT NULL,created timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS tasks_owner ON tasks(owner_id,created DESC);
CREATE INDEX IF NOT EXISTS outbox_pending ON outbox(dispatched,kafka_sent,created);
CREATE INDEX IF NOT EXISTS samples_project ON platform_samples(project_id,created DESC);
